    for(const ai of c.armies.filter((a)=>a.side==="carthage")){if(c.turn<attackTurn)continue;const adjacent=c.cities.filter((x)=>connected(c.theater,ai.cityId,x.id)&&x.owner==="rome").sort((a,b)=>a.defense-b.defense)[0];if(!adjacent)continue;const defender=c.armies.find((a)=>a.side==="rome"&&a.cityId===adjacent.id);if(defender){ai.cityId=adjacent.id;encounter=makeEncounter(c,defender,ai,adjacent,true);notes.push(`${ai.name} attacks ${adjacent.name}!`);break}if(armyPower(ai)>adjacent.defense*5+(adjacent.garrison.reduce((s,u)=>s+u.men,0))){adjacent.owner="carthage";ai.cityId=adjacent.id;notes.push(`${adjacent.name} has fallen to ${enemyFaction.name}.`)}else{ai.units.forEach((u)=>u.men=Math.max(1,u.men-Math.ceil(adjacent.defense/10)));notes.push(`${adjacent.name} repelled an enemy assault.`)}}
