function makeEncounter(c:Campaign,player:Army,enemy:Army|null,city:City,defensive:boolean):BattleContext{const enemyUnits=enemy?.units.length?enemy.units:enemyRoster(city.id,city.id,c.theater),terrains=["Plains","Hills","Forest","River"] as const,terrain=terrains[(city.id+c.turn)%terrains.length],weather=c.season==="Winter"?"Fog":c.season==="Autumn"?"Rain":c.season==="Summer"&&city.id%2===0?"Heat":"Clear",walls=city.buildings.includes("Walls")&&player.siegeTurns<2;return{units:createBattle(player.units.slice(0,8),enemyUnits.slice(0,8),defensive,walls,player.general,player.tradition,player.stance,player.supplies),reinforcements:player.units.slice(8),playerArmyId:player.id,enemyArmyId:enemy?.id??null,targetCityId:city.id,defensive,walls,terrain,weather,season:c.season,general:player.general,stance:player.stance}}
